package com.motionstudio.part6
import java.util.concurrent.atomic.LongAdder
data class PerformanceSnapshot(val fps:Double,val frameRenderMs:Double,val decodeMs:Double,val encodeMs:Double,val gpuWorkMs:Double,val memoryBytes:Long,val cacheHitRate:Double,val droppedFrames:Long)
class PerformanceMonitor{private val render=LongAdder();private val decode=LongAdder();private val encode=LongAdder();private val gpu=LongAdder();private val frames=LongAdder();private val dropped=LongAdder();private val hits=LongAdder();private val misses=LongAdder();private val start=System.nanoTime();fun recordRender(ms:Long){render.add(ms);frames.increment()};fun recordDecode(ms:Long)=decode.add(ms);fun recordEncode(ms:Long)=encode.add(ms);fun recordGpu(ms:Long)=gpu.add(ms);fun droppedFrame(){dropped.increment()};fun cacheHit(){hits.increment()};fun cacheMiss(){misses.increment()};fun snapshot(memoryBytes:Long):PerformanceSnapshot{val sec=(System.nanoTime()-start)/1e9;val n=frames.sum().coerceAtLeast(1);val total=hits.sum()+misses.sum();val hitRate=if(total==0L)0.0 else hits.sum().toDouble()/total;return PerformanceSnapshot(n/sec,render.sum().toDouble()/n,decode.sum().toDouble()/n,encode.sum().toDouble()/n,gpu.sum().toDouble()/n,memoryBytes,hitRate,dropped.sum())}}
